for (const item of $input.all()) {
  try {
    let raw = item.json.output ?? "";
    let s = (typeof raw === "string") ? raw : JSON.stringify(raw);

    s = s.replace(/^\uFEFF/, "")
         .trim()
         .replace(/^```(?:json)?\s*/i, "")
         .replace(/```$/i, "")
         .replace(/^\s*json\s*/i, "");

    if (!s.trim().startsWith("{")) {
      const m = s.match(/\{[\s\S]*\}/m);
      if (m) s = m[0];
    }

    let parsedData;
    try {
      parsedData = JSON.parse(s);
    } catch (e1) {
      s = s.replace(/\\(?!["\\/bfnrtu])/g, "\\\\");
      s = s.replace(/[\u0000-\u0019]/g, (c) => {
        if (c === "\n" || c === "\r" || c === "\t") return c;
        return "";
      });
      parsedData = JSON.parse(s);
    }

    const toArray = (v) => {
      if (Array.isArray(v)) return v;
      if (typeof v === "string" && v.trim()) {
        try { const a = JSON.parse(v); return Array.isArray(a) ? a : [v]; }
        catch { return v.split(/[;,|\n]/).map(x=>x.trim()).filter(Boolean); }
      }
      return [];
    };
    const joinList = (arr) => Array.isArray(arr) ? arr.join(", ") : "";

    const stripAccents = (str) =>
      (str || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const getInitials = (fullName) => {
      const stop = new Set(["de","da","das","do","dos","di","du","e","del","della","van","von","la","le"]);
      const tokens = stripAccents(fullName)
        .trim()
        .split(/[\s-]+/)
        .filter(t => t.length > 0);

      const initials = tokens
        .filter(t => !stop.has(t.toLowerCase()))
        .map(t => t[0].toUpperCase());

      return initials.length > 0 ? initials.join("") : (tokens[0]?.[0]?.toUpperCase() || "");
    };

    const digitsOnly = (x) => (x || "").toString().replace(/\D+/g, "");
    const normalizeBRPhone = (str) => {
      const d = digitsOnly(str);
      if (!d) return null;
      let dd = d;
      if (dd.startsWith("55") && (dd.length === 12 || dd.length === 13)) dd = dd.slice(2);

      if (dd.length === 11 || dd.length === 10) {
        const ddd = dd.slice(0, 2);
        const num = dd.slice(2);
        if (num.startsWith("9") || dd.length === 11) {
          const pretty = `(${ddd}) ${num.length === 9 ? num.slice(0,5)+'-'+num.slice(5) : num.slice(0,4)+'-'+num.slice(4)}`;
          const e164 = `+55${ddd}${num}`;
          return { pretty, e164, isCel: num.startsWith("9") };
        }
      }
      return null;
    };

    const pickCellPhone = (data) => {
      const keys = ["telefone_celular","celular","telefone","phone","mobile","contato"];
      const candidates = [];
      for (const k of keys) {
        const v = data?.[k];
        if (!v) continue;
        if (Array.isArray(v)) candidates.push(...v.map(String));
        else candidates.push(String(v));
      }
      const normed = candidates.map(normalizeBRPhone).filter(Boolean);
      return normed.find(n => n.isCel) || normed[0] || null;
    };

    const nomecompleto  = parsedData.nome_completo || "";
    const resumo        = parsedData.resumo || "";
    const minicurriculo = parsedData.minicurriculo || "";
    const habilidades   = toArray(parsedData.habilidades);
    const idiomas       = toArray(parsedData.idiomas);
    const experiencias  = toArray(parsedData.experiencias);
    const educacao      = toArray(parsedData.educacao);
    const email         = parsedData.email || null;

    let telObj = parsedData.telefone_celular ? normalizeBRPhone(parsedData.telefone_celular) : null;
    if (!telObj) telObj = pickCellPhone(parsedData);

    const fmtExp = experiencias.length ? experiencias.map(exp => {
      if (typeof exp === "string") return exp;
      return `${exp.cargo || ""} na ${exp.empresa || ""} (${exp.periodo || ""})\n${exp.descricao || ""}`.trim();
    }).join("\n\n") : "";

    const fmtEdu = educacao.length ? educacao.map(edu => {
      if (typeof edu === "string") return edu;
      return `${edu.curso || ""} em ${edu.instituicao || ""} (${edu.periodo || ""})`.trim();
    }).join("\n") : "";

    item.json.NOME_COMPLETO_CANDIDATO = nomecompleto;
    item.json.INICIAIS_NOME           = getInitials(nomecompleto);
    item.json.RESUMO_CANDIDATO        = resumo;
    item.json.MINICURRICULO_CANDIDATO = minicurriculo;
    item.json.HABILIDADES_CANDIDATO   = joinList(habilidades);
    item.json.IDIOMAS_CANDIDATO       = joinList(idiomas);
    item.json.EXPERIENCIAS_CANDIDATO  = fmtExp;
    item.json.EDUCACAO_CANDIDATO      = fmtEdu;
    item.json.EXPERIENCIAS_OBJ        = experiencias;
    item.json.EDUCACAO_OBJ            = educacao;

    item.json.TELEFONE_CELULAR        = telObj ? telObj.pretty : null;
    item.json.TELEFONE_CELULAR_E164   = telObj ? telObj.e164   : null;
    item.json.EMAIL_CANDIDATO         = email;

  } catch (error) {
    item.json.error                   = `Erro ao processar o JSON principal: ${error.message}`;
    item.json.NOME_COMPLETO_CANDIDATO = null;
    item.json.INICIAIS_NOME           = null;
    item.json.RESUMO_CANDIDATO        = null;
    item.json.MINICURRICULO_CANDIDATO = null;
    item.json.HABILIDADES_CANDIDATO   = null;
    item.json.EXPERIENCIAS_CANDIDATO  = null;
    item.json.IDIOMAS_CANDIDATO       = null;
    item.json.EDUCACAO_CANDIDATO      = null;
    item.json.EXPERIENCIAS_OBJ        = [];
    item.json.EDUCACAO_OBJ            = [];
    item.json.TELEFONE_CELULAR        = null;
    item.json.TELEFONE_CELULAR_E164   = null;
    item.json.EMAIL_CANDIDATO         = null;
  }
}
return $input.all();

// Sanear resposta do agente (tirar cercas ```json, pegar o 1º {…}, corrigir escapes) e expor campos
for (const item of $input.all()) {
  try {
    let raw = item.json.output ?? "";

    // garante string
    let s = (typeof raw === "string") ? raw : JSON.stringify(raw);

    // remove cercas de código e espaços
    s = s.replace(/^```(?:json)?\s*/i, "").replace(/```$/i, "").trim();

    // se não começa com {, extrai o primeiro bloco {…}
    if (!s.startsWith("{")) {
      const m = s.match(/\{[\s\S]*\}/m);
      if (m) s = m[0];
    }

    // tenta parse direto; se falhar, corrige escapes esquisitos e parseia
    let data;
    try {
      data = JSON.parse(s);
    } catch {
      s = s.replace(/\\(?!["\\/bfnrtu])/g, "\\\\")
           .replace(/[\u0000-\u0019]/g, (c) => 
             (c === "\n" || c === "\r" || c === "\t") ? c : ""
           );
      data = JSON.parse(s);
    }

    // Mapeia para campos individuais (prontos pro Edit Fields)
    item.json.resumo_candidato       = data.resumo_candidato ?? "";
    item.json.aderencia_tecnica      = data.aderencia_tecnica ?? "";
    item.json.gaps                   = data.gaps ?? "";
    item.json.fit_contextual         = data.fit_contextual ?? "";
    item.json.percentual_aderencia   = data.percentual_aderencia ?? 0;
    item.json.taxa_hora              = data.taxa_hora ?? "R$ 0,00";
    item.json.conclusao_recomendacao = data.conclusao_recomendacao ?? "";

  } catch (err) {
    item.json.parse_error = `Falha ao parsear saída do agente: ${err.message}`;
  }
}
return $input.all();
